from collections import Counter
def solve(I, tie='drop'):
    h,w=len(I),len(I[0])
    corners={'TL':(I[0][0],0,0),'TR':(I[0][-1],0,w-1),'BL':(I[-1][0],h-1,0),'BR':(I[-1][-1],h-1,w-1)}
    bg=Counter(x for row in I for x in row).most_common(1)[0][0]
    out=[[bg]*w for _ in range(h)]
    def cheb(i,j,c,r,c_): return max(abs(i-r),abs(j-c))
    for i in range(h):
        for j in range(w):
            best={k:cheb(i,j,kc,p,q) for k,(kc,p,q) in corners.items()}
            mind=min(best.values())
            owners=[k for k,dv in best.items() if dv==mind]
            ok = True
            if tie=='drop' and len(owners)!=1: continue
            if any(corners[k][0]==bg for k in owners) and len(owners)!=1: continue
            if any(corners[k][0]!=bg for k in owners) and len(owners)!=1:
                c=corners[[k for k in owners if corners[k][0]!=bg][0]][0]
            else: continue
            # owner = unique non-bg corner
            o=[k for k in owners if corners[k][0]!=bg]
            if len(o)!=1: continue
            c=corners[o[0]][0]
            if cheb(i,j,o[0],corners[o[0]][1],corners[o[0]][2])%2==0:
                out[i][j]=c
    return out
