# Hypothesis: multi-source BFS from all markers simultaneously (all 8 dirs), each expands one ring per step;
# cell takes color of marker whose wave arrives first (ties -> ?); unpainted if never reached (or bg stays).
def bfs_wave(met,tie):
    # met ignored-ish; tie: 'first' default
    def run():
        tot=0
        for n in range(1,9):
            A=np.array(G[f'Demo pair {n} input']); B=np.array(G[f'Demo pair {n} output'])
            h,w=A.shape; bgc=collections.Counter(int(x) for x in A.flatten()).most_common(1)[0][0]
            P=np.full((h,w),bgc)
            sources=[(ii,jj,int(A[ii][jj])) for ii in range(h) for jj in range(w) if A[ii][jj]!=bgc]
            best={}
            pq=[]
            for s_ in sources:
                dist=s_+ (0,)
                best[s_[0:2]]=(np.inf,-1)
                heapq.heappush(pq,(0,s_[0],s_[1],s_[2]))
            while pq:
                d,i,j,cv=heapq.heappop(pq)
                if best.get((i,j),(np.inf,-1))[0]>d:
                    best[(i,j)]=(d,cv)
                    P[i][j]=cv
                else: continue
                for di2 in (-1,0,1):
                    for dj2 in (-1,0,1):
                        ni,nj=i+di2,j+dj2
                        if 0<=ni<h and 0<=nj<w and (ni,nj) not in best:
                            heapq.heappush(pq,(d+1,n_i:=ni,n_j:=nj,cv))
            tot+=int((P!=B).sum())
        return tot
    return run()
