    vals={kk:int(I[p][q]) for kk,(p,q) in pos.items()}
    marks=[kk for kk,vv in vals.items() if vv!=bgc]
    P=[[bgc]*w for _ in range(h)]
    for i_ in range(h):
        for j_ in range(w):
            best=[]
            for kk in marks:
